    let d = ((z0 + dz) * u.ny + (y0 + dy)) * u.nx + (x0 + dx);
    let j = dmap[d];
    if (j == NONE) { continue; }
    let wx = select(1.0 - t.x, t.x, dx == 1u);
    let wy = select(1.0 - t.y, t.y, dy == 1u);
    let wz = select(1.0 - t.z, t.z, dz == 1u);
