  B.nb = mkb(19 * nf * 4, 'nb'); B.type = mkb(nf * 4, 'type'); B.fpos = mkb(nf * 4, 'fpos');
  B.dmap = mkb(F.dense2f.byteLength, 'dmap'); B.vel = mkb(nf * 16, 'vel');
