async function loadGeometry() {
  const bin = Uint8Array.from(atob(GEOM_B64), ch => ch.charCodeAt(0));
  if (typeof DecompressionStream === 'undefined') throw new Error('このブラウザは DecompressionStream に対応していません。');
  const ds = new Blob([bin]).stream().pipeThrough(new DecompressionStream('gzip'));
  const buf = new Uint8Array(await new Response(ds).arrayBuffer());
  [G.nx, G.ny, G.nz] = GEOM_INFO.dims; G.dx = GEOM_INFO.dx; G.base = buf;
  if (buf.length !== G.nx * G.ny * G.nz) throw new Error('形状データの大きさが合いません');
}
